// Assets and the shared database are deployed and managed entirely by ChatGPT Sites.
// @ts-ignore Generated by scripts/build-sites.mjs.
import assets from "site-assets";
import { worldApi } from "./world";
export default {
  async fetch(request: Request, env: any) {
    const path = new URL(request.url).pathname;
    if (path.startsWith("/api/")) {
      if (!env.DB)
        return Response.json(
          { ok: false, error: "The shared database is not available." },
          { status: 503 },
        );
      return worldApi(request, env.DB);
    }
    const asset =
      assets[path] || (!path.includes(".") ? assets["/index.html"] : null);
    if (!asset) return new Response("Not found", { status: 404 });
    return new Response(
      Uint8Array.from(atob(asset.base64), (c: string) => c.charCodeAt(0)),
      {
        headers: {
          "Content-Type": asset.mime,
          "Cache-Control": path.startsWith("/assets/")
            ? "public, max-age=31536000, immutable"
            : "no-cache",
          "X-Content-Type-Options": "nosniff",
        },
      },
    );
  },
};
